CREATE VIEW v7741 AS SELECT *, STDDEV_SAMP(x6.v7045) AS x1, ST_ASTEXT(ST_UNION(ST_GEOMFROMTEXT('GEOMETRYCOLLECTION(LINESTRING(3 0, 3 3), LINESTRING(0 1, 4 1))'), ST_GEOMFROMTEXT('GEOMETRYCOLLECTION()'))) AS x2 FROM v7204 AS x3, v7043 AS x6 WHERE x6.v7045 = 'db-1' AND x3.v7205 <> 'PERFORMANCE_SCHEMA'